Creating a complex smart contract involves a deep understanding of blockchain technology, smart contract programming languages like Solidity (for Ethereum), and the specific requirements of the contract you want to create. Below is a simplified example of a complex smart contract written in Solidity that implements a decentralized voting system. This contract allows for the creation of a new vote, casting votes, and tallying the results.

Please note that this is a basic example for educational purposes and should not be used in production without thorough testing and auditing by professionals.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Vote {
        string description;
        bool active;
        uint256 end;
        mapping(uint256 => uint256) votes;
    }

    struct Voter {
        bool voted;
        uint256 voteIndex;
    }

    struct Proposal {
        string description;
        uint256 voteCount;
    }

    address public owner;
    mapping(uint256 => Vote) public votes;
    Proposal[] public proposals;
    uint256 public proposalCount;
    mapping(address => Voter) public voters;

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can perform this action");
        _;
    }

    modifier voteExists(uint256 proposalId) {
        require(votes[proposalId].active, "Vote does not exist");
        _;
    }

    modifier notVoted(uint256 proposalId) {
        require(!voters[msg.sender].voted, "Already voted");
        _;
    }

    modifier withinTime(uint256 proposalId) {
        require(block.timestamp < votes[proposalId].end, "Voting period has ended");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function createVote(string memory description, uint256 duration) public onlyOwner {
        Vote storage newVote = votes[proposalCount++];
        newVote.description = description;
        newVote.active = true;
        newVote.end = block.timestamp + duration;
    }

    function castVote(uint256 proposalId) public voteExists(proposalId) notVoted(proposalId) withinTime(proposalId) {
        voters[msg.sender].voted = true;
        voters[msg.sender].voteIndex = proposalId;
        votes[proposalId].votes[msg.sender]++;
    }

    function endVote(uint256 proposalId) public onlyOwner {
        votes[proposalId].active = false;
    }

    function getWinningProposal() public view returns (uint256 winningProposalId) {
        uint256 winningVoteCount = 0;
        for (uint256 i = 0; i < proposalCount; i++) {
            if (votes[i].active) {
                if (votes[i].votes[msg.sender] > winningVoteCount) {
                    winningVoteCount = votes[i].votes[msg.sender];
                    winningProposalId = i;
                }
            }
        }
    }

    function getWinningProposalDescription() public view returns (string memory) {
        return proposals[winningProposalId].description;
    }

    function getProposalCount() public view returns (uint256) {
        return proposalCount;
    }
}
```

This contract includes the following features:
- Creation of a new vote by the owner with a description and duration.
- Casting of votes by participants during the voting period.
- Ending the vote by the owner.
- Tallying the votes to determine the winning proposal.

Remember, this is a simplified example. Real-world smart contracts require careful consideration of security, gas optimization, and edge cases. Always have your contracts audited by professionals before deploying them on the mainnet.

